"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[1912],{1912:e=>{e.exports=JSON.parse('{"concept":"Pie Chart Angle Conversion","subject":"mathematics","category":"Data Handling & Interpretation","explanation":"Pie charts represent data as angles in a circle (360\xb0). To convert: (frequency \xf7 total) \xd7 360\xb0 = angle. To find frequency from angle: (angle \xf7 360\xb0) \xd7 total = frequency. Each 1% = 3.6\xb0. This appears frequently in eleven-plus exams with real-world data like survey results or sales figures.","examples":[{"question":"In a survey of 60 students\' favorite subjects, 15 chose Math. What angle represents Math in a pie chart?","solution":"90\xb0","explanation":"Math fraction = 15/60 = 1/4. Angle = 1/4 \xd7 360\xb0 = 90\xb0."},{"question":"In a pie chart showing pet preferences, cats have an angle of 108\xb0. If 180 people were surveyed, how many chose cats?","solution":"54 people","explanation":"Cat fraction = 108\xb0/360\xb0 = 3/10. Number who chose cats = 3/10 \xd7 180 = 54 people."},{"question":"A pie chart shows: Red 120\xb0, Blue 90\xb0, Green 60\xb0, Yellow 90\xb0. What percentage is Green?","solution":"16.7% (or 1/6)","explanation":"Green angle = 60\xb0 out of 360\xb0 total. Percentage = (60/360) \xd7 100% = 16.67% = 16\u2154%."}],"exercises":[{"type":"multiple-choice","question":"In a class of 40 students, 10 like football, 15 like tennis, 8 like swimming, 7 like rugby. What\'s the angle for tennis in a pie chart?","options":["90\xb0","135\xb0","150\xb0","180\xb0"],"correct":[1],"explanation":"Tennis fraction = 15/40 = 3/8. Angle = 3/8 \xd7 360\xb0 = 135\xb0."},{"type":"multiple-choice","question":"A pie chart sector has angle 72\xb0. What percentage of the total does this represent?","options":["15%","18%","20%","25%"],"correct":[2],"explanation":"Percentage = (72\xb0/360\xb0) \xd7 100% = 1/5 \xd7 100% = 20%."},{"type":"open-ended","question":"A bakery sells 4 types of bread: White (45\xb0), Brown (90\xb0), Seeded (135\xb0), Wholemeal (?). Find the angle for Wholemeal and explain your method.","sample_answer":"Total angles in a circle = 360\xb0. White + Brown + Seeded = 45\xb0 + 90\xb0 + 135\xb0 = 270\xb0. Therefore Wholemeal = 360\xb0 - 270\xb0 = 90\xb0.","explanation":"All angles in a pie chart must sum to 360\xb0."}],"tips":["Total angles in pie chart = 360\xb0","Use proportion: (part/total) \xd7 360\xb0 = angle","Each 10% = 36\xb0, each 1% = 3.6\xb0","Check: all angles should add to 360\xb0","Convert fractions to angles by multiplying by 360\xb0"]}')}}]);